SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS metric_0001, CAST(metric_0012 AS DOUBLE PRECISION) AS metric_0012, CAST(metric_0023 AS DOUBLE PRECISION) AS metric_0023, CAST(metric_0034 AS DOUBLE PRECISION) AS metric_0034, CAST(metric_0045 AS DOUBLE PRECISION) AS metric_0045, CAST(metric_0056 AS DOUBLE PRECISION) AS metric_0056, CAST(metric_0067 AS DOUBLE PRECISION) AS metric_0067, CAST(metric_0078 AS DOUBLE PRECISION) AS metric_0078, CAST(metric_0089 AS DOUBLE PRECISION) AS metric_0089, CAST(metric_0100 AS DOUBLE PRECISION) AS metric_0100 FROM wide100 WHERE time >= '2024-12-22' AND time < '2025-01-01' ORDER BY time
